exercise.solution:
def _inteiro(valor, padrao):
    try:
        return int(valor)
    except (TypeError, ValueError):
        return padrao


def normalizar_paginacao(pagina, limite):
    pagina_final = max(1, _inteiro(pagina, 1))
    limite_final = min(100, max(1, _inteiro(limite, 20)))
    return {
        "pagina": pagina_final,
        "limite": limite_final,
        "offset": (pagina_final - 1) * limite_final,
    }

