    codigo = "conflito"

@app.exception_handler(ErroDeDominio)
async def tratar_dominio(requisicao, erro: ErroDeDominio):
    return JSONResponse(
        status_code=erro.status,
        content={"erro": str(erro), "codigo": erro.codigo},
    )


@app.exception_handler(Exception)
async def tratar_inesperado(requisicao, erro: Exception):
    # O detalhe vai para o log, com o id da requisição; nunca para a resposta.
    log.exception("erro não tratado", extra={"requisicao_id": requisicao.state.id})
    return JSONResponse(
        status_code=500,
        content={"erro": "Algo deu errado do nosso lado.", "codigo": "interno"},
    )

