exercise.solution:
STATUS = {
    "nao_encontrado": 404,
    "sem_permissao": 404,
    "dado_invalido": 422,
    "conflito": 409,
    "sem_sessao": 401,
    "limite": 429,
}


def resposta_de_erro(codigo, mensagem, detalhe=None):
    status = STATUS.get(codigo)

    if status is None:
        # Codigo desconhecido: a mensagem pode conter detalhe interno e nao sai.
        return (500, {"erro": "Algo deu errado do nosso lado.", "codigo": "interno"})

    corpo = {"erro": mensagem, "codigo": codigo}
    if detalhe is not None:
        corpo["detalhe"] = detalhe

    return (status, corpo)

