def tarefas_travadas(tarefas, agora, limite_minutos):
    travadas = []

    for tarefa in tarefas:
        if tarefa.get("estado") != "executando":
            continue

        iniciada_em = tarefa.get("iniciada_em")
        # Sem registro de inicio, nao da para saber ha quanto tempo roda:
        # tratar como travada e mais seguro que ignorar.
        if iniciada_em is None or iniciada_em > limite_minutos:
            travadas.append(tarefa["id"])

    return sorted(travadas)

